# Fields an IOC value is searched in (Elastic Common Schema)
FIELDS = {
    'ip': ['source.ip', 'destination.ip', 'client.ip', 'server.ip'],
    'domain': ['dns.question.name', 'url.domain', 'destination.domain', 'tls.client.server_name'],
    'url': ['url.full', 'url.original'],
    'md5': ['file.hash.md5', 'process.hash.md5', 'dll.hash.md5'],
    'sha1': ['file.hash.sha1', 'process.hash.sha1', 'dll.hash.sha1'],
    'sha256': ['file.hash.sha256', 'process.hash.sha256', 'dll.hash.sha256'],
    'filename': ['file.name', 'process.name'],
}
KINDS = {'ip-src': 'ip', 'ip-dst': 'ip', 'ip-any': 'ip', 'ip': 'ip', 'domain': 'domain', 'hostname': 'domain',
         'url': 'url', 'uri': 'url', 'md5': 'md5', 'sha1': 'sha1', 'sha256': 'sha256', 'filename': 'filename'}


PREFERENCE = ['sha256', 'sha1', 'md5', 'url', 'domain', 'ip', 'filename']


def target(type_name, value):
    # 'filename|sha256' and the like: the most specific component
    types = type_name.lower().split('|')
    values = value.split('|')
    found = {}
    for index, part in enumerate(types):
        kind = KINDS.get(part.strip())
        if kind is not None and kind not in found and index < len(values) and values[index].strip():
            found[kind] = values[index].strip()
    for kind in PREFERENCE:
        if kind in found:
            return [kind, found[kind]]
    return [None, None]


ioc = inputs.get('ioc') if is_dict(inputs.get('ioc')) else {}
type_name = ((ioc.get('ioc_type') or {}).get('type_name') or '').strip()
raw = (ioc.get('ioc_value') or '').strip()
kind, value = target(type_name, raw)
days = int(inputs.get('days') or 30)
if not raw:
    result = {'supported': False, 'reason': 'Empty IOC value'}
elif kind is None:
    result = {'supported': False, 'reason': f'No search for IOCs of type {type_name or "unknown"}'}
elif kind == 'ip' and ip_info(value) is None:
    result = {'supported': False, 'reason': f'{value} is not an IP address'}
else:
    if kind in ('domain', 'md5', 'sha1', 'sha256'):
        value = value.lower().rstrip('.')
    terms = [{'term': {field: value}} for field in FIELDS[kind]]
    body = {
        'size': 0,
        'track_total_hits': True,
        'query': {'bool': {'filter': [
            {'range': {'@timestamp': {'gte': f'now-{days}d'}}},
            {'bool': {'should': terms, 'minimum_should_match': 1}},
        ]}},
        'aggs': {'hosts': {
            'terms': {'field': 'host.name', 'size': 200},
            'aggs': {
                'os': {'terms': {'field': 'host.os.type', 'size': 1}},
                'ip': {'terms': {'field': 'host.ip', 'size': 1}},
                'last_seen': {'max': {'field': '@timestamp'}},
            },
        }},
    }
    result = {'supported': True, 'kind': kind, 'value': value, 'days': days, 'fields': FIELDS[kind], 'body': body}

def first_key(agg):
    buckets = (agg or {}).get('buckets') if is_dict(agg) else None
    return buckets[0].get('key') if is_list(buckets) and buckets else None


def short(name):
    return name.lower().split('.')[0]


body = inputs.get('response') if is_dict(inputs.get('response')) else {}
assets = inputs.get('assets') if is_list(inputs.get('assets')) else []
limit = int(inputs.get('max_suggestions') or 5)

names = set()
ips = set()
for asset in assets:
    for field in ('asset_name', 'asset_domain'):
        if is_str(asset.get(field)) and asset.get(field).strip():
            names.add(short(asset.get(field).strip()))
    if is_str(asset.get('asset_ip')):
        for ip in re_split('[,;\\s]+', asset.get('asset_ip')):
            if ip:
                ips.add(ip)

hosts = {}
buckets = (((body.get('aggregations') or {}).get('hosts') or {}).get('buckets'))
if is_list(buckets):
    for bucket in buckets:
        host = str(bucket.get('key') or '').strip()
        if host:
            last = (bucket.get('last_seen') or {})
            hosts[host] = {'host': host, 'hits': int(bucket.get('doc_count') or 0),
                           'os': first_key(bucket.get('os')), 'ip': first_key(bucket.get('ip')),
                           'last_seen': last.get('value_as_string')}
else:
    # No aggregation in the answer: count the returned events
    for hit in ((body.get('hits') or {}).get('hits') or []):
        source = hit.get('_source') or {}
        host_doc = source.get('host') or {}
        host = str(host_doc.get('name') or '').strip()
        if not host:
            continue
        entry = hosts.setdefault(host, {'host': host, 'hits': 0, 'os': (host_doc.get('os') or {}).get('type'),
                                        'ip': None, 'last_seen': source.get('@timestamp')})
        entry['hits'] += 1

total = (body.get('hits') or {}).get('total')
total = total.get('value') if is_dict(total) else total
ranked = sorted(hosts.values(), key=lambda h: h['hits'], reverse=True)
for entry in ranked:
    entry['known'] = short(entry['host']) in names or (entry['ip'] is not None and str(entry['ip']) in ips)
new_hosts = [h for h in ranked if not h['known']]


def line(h):
    return f"| {h['host'].replace('|', '/')} | {h['hits']} | {h['os'] or '-'} | {h['last_seen'] or '-'} |"


table = ''
if new_hosts:
    table = '\n'.join(['| Host | Events | OS | Last seen |', '|---|---|---|---|'] + [line(h) for h in new_hosts[:25]])
result = {
    'total_hits': total if total is not None else sum([h['hits'] for h in ranked]),
    'hosts': len(ranked),
    'known_hosts': [h['host'] for h in ranked if h['known']],
    'new_hosts': new_hosts,
    'new_count': len(new_hosts),
    'to_suggest': new_hosts[:limit],
    'has_new': len(new_hosts) > 0,
    'table': table,
}

TYPE_BY_OS = {'windows': 'Windows - Computer', 'linux': 'Linux - Computer', 'macos': 'Mac - Computer'}

hosts = inputs.get('hosts') if is_list(inputs.get('hosts')) else []
index = int(inputs.get('index') or 0)
if index >= len(hosts):
    fail('No host left to suggest')
host = hosts[index]
fallback = inputs.get('default_type') or 'Windows - Computer'
wanted = TYPE_BY_OS.get(str(host.get('os') or '').lower()) or fallback
ids = {}
for entry in inputs.get('types') or []:
    ids[str(entry.get('name') or '').lower()] = entry.get('id')
type_id = ids.get(wanted.lower())
if type_id is None:
    type_id = ids.get(fallback.lower())
if type_id is None:
    fail(f'No asset type named {wanted} or {fallback}: set default_type to one of the asset types of this instance')
ioc = inputs.get('ioc') or {}
payload = {
    'asset_name': host['host'],
    'asset_type_id': type_id,
    'asset_description': f"Seen with IOC {ioc.get('value')} in {host['hits']} SIEM event(s) over the last "
                         f"{ioc.get('days')} days (last seen {host.get('last_seen') or 'unknown'}).",
    'asset_tags': 'ioc-hunt',
}
if host.get('ip'):
    payload['asset_ip'] = str(host['ip'])
result = {'host': host, 'payload': payload, 'next': index + 1, 'more': index + 1 < len(hosts)}
